APP_REPLACEMENTS = [('import SlaCenterPage from "./pages/SlaCenterPage";\n', 'import SlaCenterPage from "./pages/SlaCenterPage";\nimport SlaAdvancedPage from "./pages/SlaAdvancedPage";\n'), ('        <Route path="/sla-center" component={SlaCenterPage} />\n', '        <Route path="/sla-center" component={SlaCenterPage} />\n        {user && ["team_leader", "director", "cmo", "ceo", "admin", "super_admin"].includes(user.role) ? (\n          <Route path="/sla-advanced" component={SlaAdvancedPage} />\n        ) : null}\n')]
