SCHEMA_REPLACEMENTS = [('// Export types for Drizzle ORM\n', '// =============================================\n// Advanced SLA Tables\n// =============================================\n\nexport const slaPolicies = mysqlTable(\n  "sla_policies",\n  {\n    id: int("id").autoincrement().primaryKey(),\n    name: varchar("name", { length: 191 }).notNull(),\n    scopeType: mysqlEnum("scopeType", ["company", "department", "client"])\n      .default("company")\n      .notNull(),\n    departmentId: int("departmentId").references(() => departments.id, { onDelete: "set null" }),\n    clientId: int("clientId").references(() => clients.id, { onDelete: "set null" }),\n    timezone: varchar("timezone", { length: 100 }).default("Africa/Cairo").notNull(),\n    businessDays: varchar("businessDays", { length: 32 }).default("1,2,3,4,5").notNull(),\n    businessStartMinute: int("businessStartMinute").default(540).notNull(),\n    businessEndMinute: int("businessEndMinute").default(1020).notNull(),\n    graceMinutes: int("graceMinutes").default(0).notNull(),\n    escalation1Minutes: int("escalation1Minutes").default(0).notNull(),\n    escalation2Minutes: int("escalation2Minutes").default(240).notNull(),\n    escalation3Minutes: int("escalation3Minutes").default(960).notNull(),\n    escalation1Role: varchar("escalation1Role", { length: 50 }).default("team_leader").notNull(),\n    escalation2Role: varchar("escalation2Role", { length: 50 }).default("director").notNull(),\n    escalation3Role: varchar("escalation3Role", { length: 50 }).default("ceo").notNull(),\n    isActive: boolean("isActive").default(true).notNull(),\n    createdAt: timestamp("createdAt").defaultNow().notNull(),\n    updatedAt: timestamp("updatedAt").defaultNow().onUpdateNow().notNull(),\n  },\n  (table) => ({\n    scopeIdx: index("sla_policies_scope_idx").on(table.scopeType),\n    departmentIdx: index("sla_policies_department_idx").on(table.departmentId),\n    clientIdx: index("sla_policies_client_idx").on(table.clientId),\n    activeIdx: index("sla_policies_active_idx").on(table.isActive),\n  }),\n);\n\nexport const slaBreachEvents = mysqlTable(\n  "sla_breach_events",\n  {\n    id: int("id").autoincrement().primaryKey(),\n    eventKey: varchar("eventKey", { length: 191 }).notNull(),\n    taskId: int("taskId").references(() => tasks.id, { onDelete: "set null" }),\n    employeeId: int("employeeId").references(() => employees.id, { onDelete: "set null" }),\n    policyId: int("policyId").references(() => slaPolicies.id, { onDelete: "set null" }),\n    eventType: mysqlEnum("eventType", ["breached", "escalated", "resolved"]).notNull(),\n    escalationLevel: int("escalationLevel").default(0).notNull(),\n    targetRole: varchar("targetRole", { length: 50 }),\n    taskTitle: varchar("taskTitle", { length: 500 }).notNull(),\n    employeeName: varchar("employeeName", { length: 255 }).notNull(),\n    departmentName: varchar("departmentName", { length: 191 }),\n    clientName: varchar("clientName", { length: 191 }),\n    policyName: varchar("policyName", { length: 191 }).notNull(),\n    dueDate: date("dueDate", { mode: "string" }).notNull(),\n    businessMinutesLate: int("businessMinutesLate").default(0).notNull(),\n    message: text("message"),\n    occurredAt: timestamp("occurredAt").defaultNow().notNull(),\n  },\n  (table) => ({\n    eventKeyUnique: uniqueIndex("sla_breach_events_event_key_unique").on(table.eventKey),\n    taskIdx: index("sla_breach_events_task_idx").on(table.taskId),\n    employeeIdx: index("sla_breach_events_employee_idx").on(table.employeeId),\n    occurredIdx: index("sla_breach_events_occurred_idx").on(table.occurredAt),\n  }),\n);\n\n// Export types for Drizzle ORM\n'), ('export type ClientKpi = typeof clientKpis.$inferSelect;\nexport type InsertClientKpi = typeof clientKpis.$inferInsert;\n\n', 'export type ClientKpi = typeof clientKpis.$inferSelect;\nexport type InsertClientKpi = typeof clientKpis.$inferInsert;\n\nexport type SlaPolicy = typeof slaPolicies.$inferSelect;\nexport type InsertSlaPolicy = typeof slaPolicies.$inferInsert;\n\nexport type SlaBreachEvent = typeof slaBreachEvents.$inferSelect;\nexport type InsertSlaBreachEvent = typeof slaBreachEvents.$inferInsert;\n\n')]

def run(cmd, cwd=None, check=True):
    return subprocess.run(cmd, cwd=cwd, check=check, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

def git_blob(repo: Path, path: str):
    return run(["git", "hash-object", path], cwd=repo).stdout.strip()

def assert_clean_target(repo: Path, path: str):
    unstaged = subprocess.run(["git", "diff", "--quiet", "--", path], cwd=repo)
    staged = subprocess.run(["git", "diff", "--cached", "--quiet", "--", path], cwd=repo)
    if unstaged.returncode != 0 or staged.returncode != 0:
        raise RuntimeError(f"Target file has local changes: {path}")

def replace_once(path: Path, old: str, new: str):
    content = path.read_text()
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly one anchor in {path}, found {count}")
    path.write_text(content.replace(old, new, 1))

def main():
    repo = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
    output = Path(sys.argv[2] if len(sys.argv) > 2 else "/var/tmp/TOS_SLA_ADVANCED_PHASE4.patch").resolve()

    if not (repo / ".git").exists():
        raise RuntimeError(f"Not a git repository: {repo}")

    branch = run(["git", "branch", "--show-current"], cwd=repo).stdout.strip()
    if branch != "main":
        raise RuntimeError(f"Expected branch main, found {branch or '(detached)'}")

    for path, expected in EXPECTED_BLOBS.items():
        full = repo / path
        if not full.exists():
            raise RuntimeError(f"Missing target file: {path}")
        assert_clean_target(repo, path)
        actual = git_blob(repo, path)
        if actual != expected:
            raise RuntimeError(f"Baseline mismatch for {path}: expected {expected}, found {actual}")

    for path in NEW_FILES:
        if (repo / path).exists():
            raise RuntimeError(f"New Phase 4 file already exists: {path}")

    temp_root = Path(tempfile.mkdtemp(prefix="tos-sla-advanced-phase4-"))
    worktree = temp_root / "repo"
    try:
        run(["git", "worktree", "add", "--detach", str(worktree), "HEAD"], cwd=repo)

        for old, new in APP_REPLACEMENTS:
            replace_once(worktree / TARGET_APP, old, new)
        for old, new in LAYOUT_REPLACEMENTS:
            replace_once(worktree / TARGET_LAYOUT, old, new)
        for old, new in ROUTER_REPLACEMENTS:
            replace_once(worktree / TARGET_ROUTERS, old, new)
        for old, new in SCHEMA_REPLACEMENTS:
            replace_once(worktree / TARGET_SCHEMA, old, new)

        (worktree / TARGET_SLA).write_text(SLA_TS)

        for path, content in NEW_FILES.items():
            target = worktree / path
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content)
            run(["git", "add", "-N", "--", path], cwd=worktree)

        expected_paths = sorted([TARGET_APP, TARGET_LAYOUT, TARGET_ROUTERS, TARGET_SLA, TARGET_SCHEMA, *NEW_FILES.keys()])
        changed = run(["git", "diff", "--name-only"], cwd=worktree).stdout.strip().splitlines()
        if sorted(changed) != expected_paths:
            raise RuntimeError(f"Unexpected patch scope: {changed}; expected {expected_paths}")

        patch = run(["git", "diff", "--binary", "--", *expected_paths], cwd=worktree).stdout
        if not patch.strip():
            raise RuntimeError("Generated patch is empty")
        output.write_text(patch)

        apply_check = subprocess.run(["git", "apply", "--check", str(output)], cwd=repo, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if apply_check.returncode != 0:
            raise RuntimeError(f"git apply --check failed:\n{apply_check.stderr}")

        digest = hashlib.sha256(output.read_bytes()).hexdigest()
        print(f"PATCH={output}")
        print(f"SHA256={digest}")
        print("FILES=")
        for path in expected_paths:
            print(path)
    finally:
        subprocess.run(["git", "worktree", "remove", "--force", str(worktree)], cwd=repo, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        shutil.rmtree(temp_root, ignore_errors=True)

if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        sys.exit(1)
